function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 5 || word.length > 250) return 'word needs 5 to 250 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses lowercase English letters only.';
  if (!Number.isInteger(k) || k < 0 || k > word.length - 5) return 'k is a whole number from 0 to word.length - 5.';
  return null;
}

