function countOfSubstrings(word, k) {
  const isVowel = (ch) => 'aeiou'.includes(ch);

  function atLeast(need) {
    const vowelCount = new Map();
    let consonants = 0;
    let left = 0;
    let total = 0;
    for (let right = 0; right < word.length; right++) {
      const ch = word[right];
      if (isVowel(ch)) {
        vowelCount.set(ch, (vowelCount.get(ch) || 0) + 1);
      } else {
        consonants++;
      }
      while (vowelCount.size === 5 && consonants >= need) {
        const gone = word[left];
        if (isVowel(gone)) {
          vowelCount.set(gone, vowelCount.get(gone) - 1);
          if (vowelCount.get(gone) === 0) {
            vowelCount.delete(gone);
          }
        } else {
          consonants--;
        }
        left++;
      }
      total += left;
    }
    return total;
  }

  return atLeast(k) - atLeast(k + 1);
}

