function countOfSubstrings(word, k) {
  // Slice out every substring and count its consonants and distinct vowels from scratch.
  let total = 0;
  for (let i = 0; i < word.length; i++) {
    for (let j = i + 1; j <= word.length; j++) {
      const piece = word.slice(i, j);
      const consonants = piece.split('').filter(c => !'aeiou'.includes(c)).length;
      if (consonants === k && 'aeiou'.split('').every(v => piece.includes(v))) total++;
    }
  }
  return total;
}

