function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 51) : 5 + Math.floor(rand() * 12);
  // Few consonant letters on small inputs keep repeats likely; the rate varies so some words are vowel-heavy.
  const consonantLetters = large ? 'bcdfghjklmnpqrstvwxyz' : 'qxz';
  const consonantRate = rand() * 0.5;
  let word = '';
  for (let i = 0; i < n; i++) {
    if (rand() < consonantRate) word += consonantLetters[Math.floor(rand() * consonantLetters.length)];
    else word += 'aeiou'[Math.floor(rand() * 5)];
  }
  // A window holding all five vowels has more consonants when they are common, so k follows the rate.
  const most = Math.min(n - 5, large ? 3 + Math.floor(30 * consonantRate) : 4);
  const k = Math.floor(rand() * (most + 1));
  return [word, k];
}
